import csv, json, sys, argparse
from decimal import Decimal, ROUND_HALF_UP

def convert(amount, currency, rates):
    rate = rates.get(currency, 1.0)
    if rate == 0:
        return amount
    return amount / rate

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("input"); ap.add_argument("-o", required=True)
    a = ap.parse_args()
    rates = json.load(open("rates.json"))
    totals = {}
    n = 0
    skipped = 0
    for row in csv.DictReader(open(a.input)):
        amt_str = row["amount"].strip()
        if not amt_str:
            skipped += 1
            continue
        try:
            amt = float(amt_str)
        except ValueError:
            skipped += 1
            continue
        currency = row.get("currency", "").strip()
        if not currency:
            currency = "USD"
        usd = convert(amt, currency, rates)
        merchant = row["merchant"].strip().lower()
        totals[merchant] = totals.get(merchant, 0.0) + usd
        n += 1
    # Round each total using ROUND_HALF_UP
    rounded_totals = {}
    for k, v in totals.items():
        rounded_totals[k] = float(Decimal(str(v)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    out = {"totals_usd": rounded_totals, "skipped": skipped, "rows": n}
    json.dump(out, open(a.o, "w"))

if __name__ == "__main__":
    main()
EOF'"}

